effect.shader:
const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);
const vec3 TEAL = vec3(0.18, 0.55, 0.60);
const vec3 LARANJA = vec3(1.0, 0.55, 0.20);

void main() {
    vec4 c = texture(inputImg, acScreenNorm);
    float l = dot(c.rgb, LUMA);
    // Contraste em torno de 0.5
    l = clamp((l - 0.5) * contrast + 0.5, 0.0, 1.0);

    vec3 cor = mix(TEAL, LARANJA, l);
    vec3 grad = mix(vec3(l), cor, 0.35 * strength);

    // Saturação local
    float lg = dot(grad, LUMA);
    grad = mix(vec3(lg), grad, sat);

    fragColor = vec4(mix(c.rgb, grad, strength), c.a);
}
